import {loadCatalogue,loadWeapons,loadRules} from './explorer-data.mjs?v=tools2';
import {weaponMetrics,powerMultiplier} from './explorer-model.mjs?v=tools2';
import {el,heading,button,field,input,select,itemSummary,picker,inspect,copyLink} from './explorer-ui.mjs?v=effectscompact1';
export async function setupCompare(){
 const [catalogue,weapons,rules]=await Promise.all([loadCatalogue(),loadWeapons(),loadRules()]),items=new Map(catalogue.items.filter(i=>weapons[i.slug]).map(i=>[i.slug,i])),panel=document.getElementById('compare-panel');panel.replaceChildren();panel.classList.add('tool-page');
 heading(panel,'COMPARE','装备对比','比较两件武器的基础属性、连招与随机效果池。');
 const choose=picker();let kind='melee',a='sword',b='heartbreaker',threat=8,difficulty='normal',pa=53,pb=53;
 const toolbar=el('div','tool-toolbar'),kindSelect=select([['melee','近战武器'],['ranged','远程武器']],'melee',v=>{kind=v;[a,b]=v==='melee'?['sword','heartbreaker']:['bow','crossbow'];update();});kindSelect.setAttribute('aria-label','对比武器类型');toolbar.append(kindSelect,button('交换左右',()=>{[a,b]=[b,a];[pa,pb]=[pb,pa];update();}),button('分享对比',()=>copyLink(query())));
 const selection=el('div','tool-compare-selection'),metrics=el('section','tool-card tool-compare-metrics'),power=el('section','tool-card tool-compare-power'),combo=el('section','tool-card tool-compare-combo'),pools=el('section','tool-card tool-compare-pools');panel.append(toolbar,selection,metrics,power,combo,pools,el('p','tool-note','基础属性不包含附魔、随机效果及临时状态。需查看整套搭配时，可前往配装规划。'));
 const format=(v,unit='')=>Number(v.toFixed(2)).toLocaleString('zh-CN',{maximumFractionDigits:2})+(unit?' '+unit:'');
 function query(){return 'compare&'+new URLSearchParams({kind,a,b,threat,difficulty,pa,pb});}
 function update(){history.replaceState(null,'','#'+query());render();}
 function render(){kindSelect.value=kind;selection.replaceChildren(...[a,b].map((id,n)=>{const item=items.get(id),card=el('div','tool-card tool-compare-pick');card.append(el('h3','tool-section-heading',n?'对比装备':'已装备'),itemSummary(item));const actions=el('div','tool-action-row');actions.append(button('更换武器',()=>choose.open(n?'选择右侧武器':'选择左侧武器',[...items.values()].filter(i=>i.kind===kind),selected=>{n?b=selected.slug:a=selected.slug;update();}),''),button('查看详情',()=>inspect(item)));card.append(actions);return card;}));
  const left=weaponMetrics(weapons[a]),right=weaponMetrics(weapons[b]);metrics.replaceChildren(el('h3','tool-section-heading','基础属性'));const legend=el('div','tool-stat-legend');legend.append(el('span','',items.get(a).name),el('span','',items.get(b).name));metrics.append(legend);
  const list=el('div','tool-compare-stats');
  left.forEach((l,n)=>{const r=right[n],row=el('div','tool-compare-stat'),max=Math.max(...[...items.values()].filter(i=>i.kind===kind).map(i=>weaponMetrics(weapons[i.slug]).find(s=>s.id===l.id)?.value||0),1),delta=r.value-l.value,label=el('div','tool-stat-label');label.append(el('span','',l.name),el('span',Math.abs(delta)<1e-8?'meta':(l.lower?delta<0:delta>0)?'tool-positive':'tool-negative',Math.abs(delta)<1e-8?'—':(delta>0?'+':'')+format(delta,l.unit)));row.append(label);const pair=el('div','tool-stat-pair');for(const stat of [l,r]){const line=el('div','tool-stat-line'),bar=el('span','tool-compare-bar'),fill=el('i');fill.style.width=(stat.value/max*100)+'%';bar.append(fill);line.append(bar,el('strong','',format(stat.value,stat.unit)));pair.append(line);}row.append(pair);list.append(row);});metrics.append(list,el('p','tool-note','条形长度以同类武器的最高基础属性为基准。绿色表示右侧更有利，红色表示左侧更有利；耗时越短越有利。'));
  renderPower(left,right);renderCombo();renderPools();
 }
 function renderPower(left,right){power.replaceChildren(el('h3','tool-section-heading','按物品战力换算'));const controls=el('div','tool-power-controls'),target=t=>Math.trunc((t-1)*rules.power.levels_per_threat*rules.power.power_per_level)+1;
  const t=select(Array.from({length:20},(_,i)=>[String(i+1),String(i+1)]),String(threat),v=>{const old=target(threat);threat=Number(v);if(pa===old)pa=target(threat);if(pb===old)pb=target(threat);update();}),d=select([['low','简单'],['normal','普通'],['high','困难']],difficulty,v=>{difficulty=v;update();});controls.append(field('威胁等级',t),field('难度',d));for(const [n,value] of [['left',pa],['right',pb]]){const control=input('number','',String(value));control.min='1';control.max='250';control.step='1';control.addEventListener('change',()=>{const clean=Math.min(250,Math.max(1,Math.trunc(Number(control.value)||target(threat))));n==='left'?pa=clean:pb=clean;update();});controls.append(field(n==='left'?'左侧物品战力':'右侧物品战力',control));}power.append(controls);const row=el('div','tool-power-result');for(const [id,base,p] of [[a,left,pa],[b,right,pb]]){const factor=powerMultiplier(rules.power,threat,p,difficulty),stat=base.find(s=>s.id===(kind==='melee'?'dps':'shot')),card=el('div');card.append(el('span','meta',items.get(id).name),el('strong','',format(stat.value*factor)),el('span','meta',(kind==='melee'?'每秒伤害':'齐射伤害')+' · 倍率 '+format(factor)));row.append(card);}power.append(row,el('p','tool-note','当前威胁等级的目标战力：'+target(threat)+'。换算使用游戏的战力曲线及难度倍率。'));
 }
 function renderCombo(){combo.replaceChildren(el('h3','tool-section-heading',kind==='melee'?'逐段连招与跳跃攻击':'射击机制'));const grid=el('div','tool-compare-breakdown');for(const id of [a,b]){const item=items.get(id),stats=weapons[id],side=el('div');side.append(el('h4','',item.name));if(kind==='melee'){for(const [n,hit] of stats.melee.combo.entries()){const row=el('div','tool-attack-row');row.append(el('strong','',`第 ${n+1} 段 · ${hit.hits} 次命中`),el('p','',`每次伤害 ${format(hit.damage)} · 耗时 ${format(hit.time,'秒')}`),el('p','meta',`硬直 ${format(hit.stagger)} · 距离 ${format(hit.range/100,'格')}`));side.append(row);}const jump=stats.melee.jump;side.append(el('div','tool-attack-row',`跳跃攻击：伤害 ${format(jump.damage)} · 距离 ${format(jump.range/100,'格')}`));}else{const r=stats.ranged;for(const [label,value] of [['蓄力伤害倍率','×'+r.charge_damage],['跳跃射击倍率','×'+r.jump_damage],['必须蓄力',r.charge_required?'是':'否'],['弹丸穿透',r.projectiles.some(p=>p.pierce)?'是':'否'],['齐射次数',r.volleys]])side.append(el('div','tool-attack-row',label+'：'+value));}grid.append(side);}combo.append(grid);}
 function renderPools(){pools.replaceChildren(el('h3','tool-section-heading','随机效果池'));const current=items.get(a),other=items.get(b),grid=el('div','tool-compare-breakdown');
  // The light comparison data contains weapon stats; load exact effect pools on demand.
  for(const item of [current,other]){const side=el('div');side.append(el('h4','',item.name),el('p','meta','正在读取可用效果…'));grid.append(side);}pools.append(grid);const target=a+'|'+b;pools.dataset.pair=target;import('./explorer-data.mjs?v=tools2').then(m=>m.loadLoadouts()).then(loadouts=>{if(pools.dataset.pair!==target)return;const sets=[a,b].map(id=>new Set(loadouts[id].pool.map(tag=>rules.templates.find(t=>t.tag===tag)?.effect).filter(Boolean)));[...grid.children].forEach((side,n)=>{side.lastChild.remove();const list=el('div','tool-pool-chips');for(const effect of sets[n]){const common=sets[1-n].has(effect),chip=el('span','info-chip'+(common?'':' tool-pool-exclusive'),rules.effects[effect].name);chip.title=common?'两件武器都可能出现':'仅此侧武器可能出现';list.append(chip);}side.append(list);});pools.append(el('p','tool-note','金色标记为这一侧独有的随机效果。'));}).catch(()=>{if(pools.dataset.pair===target)for(const side of grid.children)side.lastChild.textContent='效果池读取失败，请重新选择武器重试。';});
 }
 return {show(params){kind=params.get('kind')==='ranged'?'ranged':'melee';const defaults=kind==='melee'?['sword','heartbreaker']:['bow','crossbow'];a=items.get(params.get('a'))?.kind===kind?params.get('a'):defaults[0];b=items.get(params.get('b'))?.kind===kind?params.get('b'):defaults[1];threat=Math.min(20,Math.max(1,Math.trunc(Number(params.get('threat'))||8)));difficulty=['low','normal','high'].includes(params.get('difficulty'))?params.get('difficulty'):'normal';const target=Math.trunc((threat-1)*rules.power.levels_per_threat*rules.power.power_per_level)+1;pa=Math.min(250,Math.max(1,Math.trunc(Number(params.get('pa'))||target)));pb=Math.min(250,Math.max(1,Math.trunc(Number(params.get('pb'))||target)));render();}};
}
